// bundle.js — generated by build.js, do not edit by hand.
// Exposes window.generatePuzzle / classifyDifficulty / DIFFICULTIES.
(function () {
  "use strict";
// core.js — shared helpers for the Nonograms project (no dependencies).
//
// Data model
//   puzzle  = { width, height, rowClues: number[][], colClues: number[][] }
//   grid    = BigInt[] — one bitmask per row; bit c of row r is cell (r, c);
//             a set bit means the cell is FILLED.
//
// BigInt bitmasks are used so lines are not limited to 32/53 bits.

// Mask with the low `n` bits set.
function FULL(n) {
  return (1n << BigInt(n)) - 1n;
}

// Number of set bits in a mask.
function popcount(mask) {
  let c = 0;
  while (mask) {
    mask &= mask - 1n;
    c++;
  }
  return c;
}

// Deterministic PRNG (mulberry32) so --seed results are reproducible.
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Clues of a single line given as a bitmask of its filled cells.
function lineClues(mask, n) {
  const clues = [];
  let run = 0;
  for (let i = 0; i < n; i++) {
    if ((mask >> BigInt(i)) & 1n) {
      run++;
    } else if (run) {
      clues.push(run);
      run = 0;
    }
  }
  if (run) clues.push(run);
  return clues;
}

// Row and column clues of a whole grid.
function cluesFromGrid(rows, width, height) {
  const rowClues = rows.map((r) => lineClues(r, width));
  const colClues = [];
  for (let c = 0; c < width; c++) {
    let mask = 0n;
    for (let r = 0; r < height; r++) {
      if ((rows[r] >> BigInt(c)) & 1n) mask |= 1n << BigInt(r);
    }
    colClues.push(lineClues(mask, height));
  }
  return { rowClues, colClues };
}

// Does a grid satisfy a set of clues exactly?
function matchesClues(rows, width, height, rowClues, colClues) {
  for (let r = 0; r < height; r++) {
    const a = lineClues(rows[r], width);
    if (a.length !== rowClues[r].length || a.some((v, i) => v !== rowClues[r][i])) return false;
  }
  for (let c = 0; c < width; c++) {
    let mask = 0n;
    for (let r = 0; r < height; r++) {
      if ((rows[r] >> BigInt(c)) & 1n) mask |= 1n << BigInt(r);
    }
    const a = lineClues(mask, height);
    if (a.length !== colClues[c].length || a.some((v, i) => v !== colClues[c][i])) return false;
  }
  return true;
}

// All completions of a line of length n matching `clues` and consistent with
// `filled` / `empty` (bitmasks of cells already known to be filled / empty).
// Returns { masks: BigInt[], truncated } — `truncated` means the list hit the
// cap and is incomplete (callers treat that line as unconstrained).
function lineMasks(n, clues, filled = 0n, empty = 0n, cap = 20000) {
  const k = clues.length;
  if (k === 0) {
    return { masks: filled === 0n ? [0n] : [], truncated: false };
  }
  // rest[i] = minimum span needed to place blocks i..k-1
  const rest = new Array(k + 1).fill(0);
  for (let i = k - 1; i >= 0; i--) {
    rest[i] = clues[i] + (i < k - 1 ? 1 : 0) + rest[i + 1];
  }
  const masks = [];
  let truncated = false;

  const rec = (idx, pos, mask) => {
    if (truncated) return;
    if (idx === k) {
      if ((mask & filled) === filled && (mask & empty) === 0n) {
        if (masks.length === cap) {
          truncated = true;
          return;
        }
        masks.push(mask);
      }
      return;
    }
    const len = clues[idx];
    const maxPos = n - rest[idx];
    for (let s = pos; s <= maxPos; s++) {
      // cells pos..s-1 form the gap after the previous block and must be empty
      if ((FULL(s) & ~FULL(pos)) & filled) continue;
      const block = FULL(len) << BigInt(s);
      if (block & empty) continue; // block must not cover a known-empty cell
      rec(idx + 1, s + len + 1, mask | block);
    }
  };
  rec(0, 0, 0n);
  return { masks, truncated };
}

// Bitmask rows from a 2D 0/1 array.
function rowsFromArrays(grid, width) {
  return grid.map((row) => {
    let m = 0n;
    for (let c = 0; c < width; c++) if (row[c]) m |= 1n << BigInt(c);
    return m;
  });
}

// 2D 0/1 array from bitmask rows.
function rowsToArrays(rows, width) {
  return rows.map((row) => {
    const a = [];
    for (let c = 0; c < width; c++) a.push((row >> BigInt(c)) & 1n ? 1 : 0);
    return a;
  });
}

// ASCII rendering of a grid ('#' filled, '.' empty).
function renderGrid(rows, width) {
  return rows
    .map((row) => {
      let s = '';
      for (let c = 0; c < width; c++) s += (row >> BigInt(c)) & 1n ? '#' : '.';
      return s;
    })
    .join('\n');
}

// Plain-text puzzle format:
//   line 1:      "<width> <height>"
//   next height: row clues, space separated ("0" or blank = empty line)
//   next width:  column clues, space separated
// Lines starting with '#' are comments.
function parseTextPuzzle(text) {
  const lines = text
    .split('\n')
    .map((l) => l.trim())
    .filter((l) => l !== '' && !l.startsWith('#'));
  const head = lines[0].split(/\s+/).map(Number);
  const width = head[0];
  const height = head[1];
  const readClues = (line) =>
    line === undefined || line === '' ? [] : line.split(/\s+/).map(Number).filter((v) => v > 0);
  const rowClues = [];
  for (let r = 0; r < height; r++) rowClues.push(readClues(lines[1 + r]));
  const colClues = [];
  for (let c = 0; c < width; c++) colClues.push(readClues(lines[1 + height + c]));
  return { width, height, rowClues, colClues };
}

// Accepts either the JSON written by generator.js or plain text (see above).
function parsePuzzle(text) {
  const t = text.trim();
  if (t.startsWith('{')) {
    const j = JSON.parse(t);
    const rowClues = j.rowClues ?? j.clues?.rows ?? j.rows;
    const colClues = j.colClues ?? j.clues?.cols ?? j.cols;
    return {
      width: j.width ?? colClues.length,
      height: j.height ?? rowClues.length,
      rowClues,
      colClues,
    };
  }
  return parseTextPuzzle(t);
}

// Minimal --flag parsing shared by the CLIs.
function parseArgs(argv) {
  const out = { _: [] };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a.startsWith('--')) {
      const key = a.slice(2);
      const next = argv[i + 1];
      if (next !== undefined && !next.startsWith('--')) {
        out[key] = /^\d+$/.test(next) ? Number(next) : next;
        i++;
      } else {
        out[key] = true;
      }
    } else {
      out._.push(a);
    }
  }
  return out;
}

// solver.js — enumerates ALL solutions of a nonogram puzzle (CLI included).
//
// Algorithm: backtracking with line-constraint propagation.
//   1. For every row and column, precompute all completions of the line that
//      match its clues (bitmask enumeration, see core.js#lineMasks).
//   2. Propagate to a fixpoint: for each line keep only completions consistent
//      with the cells fixed so far; a cell that is filled (empty) in every
//      remaining completion of its line gets fixed.
//   3. A line with no completions left is a contradiction → backtrack.
//   4. Branch on the most-constrained undecided cell (fewest completions in
//      its line and in the crossing line), trying the likelier value first.
// Every leaf is validated against the clues before being counted, so results
// are exact even for pathological inputs.






// opts: { maxSolutions = 1e6, timeBudgetMs = Infinity }
// Returns { solutions: BigInt[][], count, truncated, timedOut, nodes,
//           lineSolvablePercent, elapsedMs }
function solvePuzzle(puzzle, opts = {}) {
  const { width: n, height: m, rowClues, colClues } = puzzle;
  const maxSolutions = opts.maxSolutions ?? 1_000_000;
  const timeBudgetMs = opts.timeBudgetMs ?? Infinity;
  const t0 = Date.now();
  const elapsed = () => Date.now() - t0;

  const rowFilled = new Array(m).fill(0n);
  const rowEmpty = new Array(m).fill(0n);
  const colFilled = new Array(n).fill(0n);
  const colEmpty = new Array(n).fill(0n);

  // Base completions per line (null = too many to enumerate → unconstrained).
  const rowMasks = rowClues.map((c) => {
    const r = lineMasks(n, c);
    return r.truncated ? null : r.masks;
  });
  const colMasks = colClues.map((c) => {
    const r = lineMasks(m, c);
    return r.truncated ? null : r.masks;
  });

  const validMasks = (base, filled, empty) => {
    if (base === null) return null;
    const out = [];
    for (const mk of base) {
      if ((mk & filled) === filled && (mk & empty) === 0n) out.push(mk);
    }
    return out;
  };

  // Fix the cells forced by every remaining completion of each line.
  // Returns false on contradiction.
  const propagate = () => {
    let changed = true;
    while (changed) {
      changed = false;
      for (let r = 0; r < m; r++) {
        const v = validMasks(rowMasks[r], rowFilled[r], rowEmpty[r]);
        if (v === null) continue;
        if (v.length === 0) return false;
        let all = v[0];
        let any = 0n;
        for (let i = 0; i < v.length; i++) {
          all &= v[i];
          any |= v[i];
        }
        const f1 = all; // filled in every completion
        const f0 = FULL(n) & ~any; // empty in every completion
        const nf = f1 & ~rowFilled[r];
        const ne = f0 & ~rowEmpty[r];
        if (nf !== 0n || ne !== 0n) {
          changed = true;
          rowFilled[r] |= f1;
          rowEmpty[r] |= f0;
          for (let c = 0; c < n; c++) {
            const bit = 1n << BigInt(c);
            if (nf & bit) colFilled[c] |= 1n << BigInt(r);
            if (ne & bit) colEmpty[c] |= 1n << BigInt(r);
          }
        }
      }
      for (let c = 0; c < n; c++) {
        const v = validMasks(colMasks[c], colFilled[c], colEmpty[c]);
        if (v === null) continue;
        if (v.length === 0) return false;
        let all = v[0];
        let any = 0n;
        for (let i = 0; i < v.length; i++) {
          all &= v[i];
          any |= v[i];
        }
        const f1 = all;
        const f0 = FULL(m) & ~any;
        const nf = f1 & ~colFilled[c];
        const ne = f0 & ~colEmpty[c];
        if (nf !== 0n || ne !== 0n) {
          changed = true;
          colFilled[c] |= f1;
          colEmpty[c] |= f0;
          for (let r = 0; r < m; r++) {
            const bit = 1n << BigInt(r);
            if (nf & bit) rowFilled[r] |= 1n << BigInt(c);
            if (ne & bit) rowEmpty[r] |= 1n << BigInt(c);
          }
        }
      }
    }
    return true;
  };

  if (!propagate()) {
    return {
      solutions: [],
      count: 0,
      truncated: false,
      timedOut: false,
      nodes: 0,
      lineSolvablePercent: 0,
      elapsedMs: elapsed(),
    };
  }

  const determinedCells = () => {
    let cnt = 0;
    for (let r = 0; r < m; r++) {
      for (let c = 0; c < n; c++) {
        const bit = 1n << BigInt(c);
        if ((rowFilled[r] & bit) || (rowEmpty[r] & bit)) cnt++;
      }
    }
    return cnt;
  };
  const lineSolvablePercent = Math.round((100 * determinedCells()) / (n * m));

  const solutions = [];
  let nodes = 0;
  let truncated = false;
  let timedOut = false;

  const search = () => {
    if (timedOut || truncated) return;
    nodes++;
    if ((nodes & 255) === 0 && elapsed() > timeBudgetMs) {
      timedOut = true;
      return;
    }

    // Complete? (state is consistent because propagate() ended without a
    // contradiction, so rows determined ⇔ all cells determined)
    let complete = true;
    for (let r = 0; r < m; r++) {
      if ((rowFilled[r] | rowEmpty[r]) !== FULL(n)) {
        complete = false;
        break;
      }
    }
    if (complete) {
      if (matchesClues(rowFilled, n, m, rowClues, colClues)) {
        if (solutions.length < maxSolutions) solutions.push(rowFilled.slice());
        else truncated = true;
      }
      return;
    }

    // Choose the line with the fewest remaining completions (>= 2).
    let best = null; // { kind: 'row'|'col', idx, v: BigInt[]|null }
    for (let r = 0; r < m; r++) {
      if (rowMasks[r] === null) continue;
      const v = validMasks(rowMasks[r], rowFilled[r], rowEmpty[r]);
      if (v.length >= 2 && (best === null || v.length < best.v.length)) {
        best = { kind: 'row', idx: r, v };
      }
    }
    for (let c = 0; c < n; c++) {
      if (colMasks[c] === null) continue;
      const v = validMasks(colMasks[c], colFilled[c], colEmpty[c]);
      if (v.length >= 2 && (best === null || v.length < best.v.length)) {
        best = { kind: 'col', idx: c, v };
      }
    }

    const cells = [];
    if (best !== null) {
      const len = best.kind === 'row' ? n : m;
      const f = best.kind === 'row' ? rowFilled[best.idx] : colFilled[best.idx];
      const e = best.kind === 'row' ? rowEmpty[best.idx] : colEmpty[best.idx];
      for (let i = 0; i < len; i++) {
        const bit = 1n << BigInt(i);
        if (!(f & bit) && !(e & bit)) cells.push(i);
      }
    } else {
      // Every non-null line is determined yet the grid is not complete: only
      // possible with truncated (null) lines. Take any undecided cell.
      outer: for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
          const bit = 1n << BigInt(c);
          if (!(rowFilled[r] & bit) && !(rowEmpty[r] & bit)) {
            best = { kind: 'row', idx: r, v: null };
            cells.push(c);
            break outer;
          }
        }
      }
    }
    if (cells.length === 0) return; // should not happen

    // Among the candidates, branch on the cell whose crossing line is most
    // constrained; tie-break by how lopsided the completions' votes are.
    const crossCount = (i) => {
      if (best.kind === 'row') {
        if (colMasks[i] === null) return Infinity;
        return validMasks(colMasks[i], colFilled[i], colEmpty[i]).length;
      }
      if (rowMasks[i] === null) return Infinity;
      return validMasks(rowMasks[i], rowFilled[i], rowEmpty[i]).length;
    };
    let bestCell = cells[0];
    let bestCross = Infinity;
    let bestSkew = -1;
    for (const i of cells) {
      const cross = crossCount(i);
      if (cross > bestCross) continue;
      let skew = 0;
      if (best.v !== null) {
        let ones = 0;
        // Bit of cell i inside the line's mask: 1<<i works for rows; for a
        // column line the mask is indexed by row, so the bit is 1<<idx.
        const bit = best.kind === 'row' ? 1n << BigInt(i) : 1n << BigInt(best.idx);
        for (const mk of best.v) if (mk & bit) ones++;
        skew = Math.abs(2 * ones - best.v.length);
      }
      if (cross < bestCross || skew > bestSkew) {
        bestCross = cross;
        bestSkew = skew;
        bestCell = i;
      }
    }

    const r = best.kind === 'row' ? best.idx : bestCell;
    const c = best.kind === 'row' ? bestCell : best.idx;
    const bitR = 1n << BigInt(c);
    const bitC = 1n << BigInt(r);
    const saved = [rowFilled.slice(), rowEmpty.slice(), colFilled.slice(), colEmpty.slice()];
    const restore = () => {
      for (let i = 0; i < m; i++) {
        rowFilled[i] = saved[0][i];
        rowEmpty[i] = saved[1][i];
      }
      for (let i = 0; i < n; i++) {
        colFilled[i] = saved[2][i];
        colEmpty[i] = saved[3][i];
      }
    };
    const tryValue = (value) => {
      if (value) {
        rowFilled[r] |= bitR;
        colFilled[c] |= bitC;
      } else {
        rowEmpty[r] |= bitR;
        colEmpty[c] |= bitC;
      }
      if (propagate()) search();
    };

    // Try the value supported by more completions first.
    // Same bit-index rule as the skew votes above.
    const voteBit2 = best.kind === 'row' ? bitR : bitC;
    let ones = null;
    if (best.v !== null) {
      let cnt = 0;
      for (const mk of best.v) if (mk & voteBit2) cnt++;
      ones = cnt;
    }
    if (ones !== null && ones * 2 < best.v.length) {
      tryValue(0);
      restore();
      tryValue(1);
    } else {
      tryValue(1);
      restore();
      tryValue(0);
    }
  };

  search();

  return {
    solutions,
    count: solutions.length,
    truncated,
    timedOut,
    nodes,
    lineSolvablePercent,
    elapsedMs: elapsed(),
  };
}

// ---------------------------------------------------------------------------

// generator.js — instantly creates nonogram puzzles with a few solutions
// (unique by default) that are fun to play. CLI included.
//
// How it works:
//   1. Draw a structured random picture (symmetric blobs, blobs, diagonal
//      stripes or checkerboard) with a healthy fill ratio.
//   2. Derive the row/column clues from the picture.
//   3. Prove the solution count with the solver. If rivals exist, flip one
//      cell where the picture disagrees with a found rival and re-prove —
//      this drives the puzzle toward uniqueness very quickly.
//   4. Accept the puzzle only if its difficulty (how far pure line solving
//      gets + how much search the uniqueness proof needed) is in range.
//   5. Redraw if a candidate cannot be fixed within the attempt budget.
// Seeded (--seed), so every puzzle is reproducible.







const DIFFICULTIES = ['Trivial', 'Easy', 'Medium', 'Hard', 'Expert'];

// How hard a puzzle feels for a human, estimated from how the uniqueness
// proof went: how much branching the solver needed (a proxy for the
// lookahead a human needs), and whether pure line-solving alone solves it.
// Thresholds scale with the cell count — a 20x20 that needs 100 branch nodes
// is easy, a 5x5 that needs 100 is brutal.
function classifyDifficulty(lineSolvablePercent, nodes, cells = 100) {
  const scale = Math.max(1, cells / 100);
  if (nodes <= 1) {
    // No real lookahead: difficulty is then mostly about size.
    return cells < 64 ? 'Trivial' : 'Easy';
  }
  if (nodes <= 3 * scale) return 'Easy';
  if (nodes <= 30 * scale) return 'Medium';
  if (nodes <= 300 * scale) return 'Hard';
  return 'Expert';
}

// ---------------------------------------------------------------------------
// Patterns — each returns bitmask rows for a w×h picture.
// ---------------------------------------------------------------------------

// Random blobs (ellipses / rectangles) until roughly targetFill is reached.
function randomBlobs(w, h, rand, targetFill = 0.5) {
  const rows = new Array(h).fill(0n);
  let filled = 0;
  const total = w * h;
  for (let guard = 0; guard < 400 && filled / total < targetFill; guard++) {
    const cx = Math.floor(rand() * w);
    const cy = Math.floor(rand() * h);
    const rx = 1 + Math.floor(rand() * Math.max(1, w / 3));
    const ry = 1 + Math.floor(rand() * Math.max(1, h / 3));
    const rect = rand() < 0.35;
    for (let y = Math.max(0, cy - ry); y <= Math.min(h - 1, cy + ry); y++) {
      for (let x = Math.max(0, cx - rx); x <= Math.min(w - 1, cx + rx); x++) {
        const inside = rect || ((x - cx) / rx) ** 2 + ((y - cy) / ry) ** 2 <= 1;
        if (!inside) continue;
        const bit = 1n << BigInt(x);
        if (!(rows[y] & bit)) {
          rows[y] |= bit;
          filled++;
        }
      }
    }
  }
  return rows;
}

// Blobs in a base region, then mirrored (h / v / both / 180° rotation).
function makeSymmetric(w, h, rand) {
  const type = Math.floor(rand() * 4);
  const baseW = type === 0 ? w : Math.ceil(w / 2);
  const baseH = type === 1 ? h : Math.ceil(h / 2);
  const base = randomBlobs(baseW, baseH, rand);
  const rows = new Array(h).fill(0n);
  const set = (y, x) => {
    rows[y] |= 1n << BigInt(x);
  };
  for (let y = 0; y < baseH; y++) {
    for (let x = 0; x < baseW; x++) {
      if (!((base[y] >> BigInt(x)) & 1n)) continue;
      if (type === 0) {
        set(y, x);
        set(h - 1 - y, x);
      } else if (type === 1) {
        set(y, x);
        set(y, w - 1 - x);
      } else if (type === 2) {
        set(y, x);
        set(y, w - 1 - x);
        set(h - 1 - y, x);
        set(h - 1 - y, w - 1 - x);
      } else {
        set(y, x);
        set(h - 1 - y, w - 1 - x);
      }
    }
  }
  return rows;
}

// Stamp a few 2x2 filled squares and 2x2 holes onto a picture. Striped
// patterns (diagonal / checker) have translation degeneracies — shifted
// copies satisfy nearly the same clues — and these distinctive anchors break
// that symmetry so the puzzle collapses toward a unique solution.
function addAnchors(rows, w, h, rand, count) {
  for (let i = 0; i < count; i++) {
    const ax = Math.floor(rand() * (w - 1));
    const ay = Math.floor(rand() * (h - 1));
    for (let dy = 0; dy < 2; dy++) {
      for (let dx = 0; dx < 2; dx++) rows[ay + dy] |= 1n << BigInt(ax + dx);
    }
  }
  for (let i = 0; i < count; i++) {
    const ax = Math.floor(rand() * (w - 1));
    const ay = Math.floor(rand() * (h - 1));
    for (let dy = 0; dy < 2; dy++) {
      for (let dx = 0; dx < 2; dx++) rows[ay + dy] &= ~(1n << BigInt(ax + dx));
    }
  }
  return rows;
}

// Diagonal stripes with a little noise. Noise is scaled down for big grids:
// noise cells create huge families of near-identical rival solutions that
// make uniqueness hard to reach.
function makeDiagonal(w, h, rand) {
  const dir = rand() < 0.5 ? 1 : -1;
  const period = 4 + Math.floor(rand() * 2); // 4..5
  const phase = Math.floor(rand() * period);
  const noise = w * h >= 144 ? 0.02 : 0.06;
  const rows = new Array(h).fill(0n);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const v = (((x + dir * y) % period) + period) % period;
      const on = v === phase || v === (phase + 1) % period;
      if (on ? rand() > noise : rand() < noise) rows[y] |= 1n << BigInt(x);
    }
  }
  return addAnchors(rows, w, h, rand, w * h >= 144 ? 2 : 1);
}

// Checkerboard with a little noise (scaled down for big grids, see above).
// A pure checkerboard has exactly 2 solutions, so uniqueness is close at hand.
function makeChecker(w, h, rand) {
  const phase = Math.floor(rand() * 2);
  const noise = w * h >= 144 ? 0.03 : 0.12;
  const rows = new Array(h).fill(0n);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      if (((x + y) & 1) === phase && rand() > noise) rows[y] |= 1n << BigInt(x);
    }
  }
  return addAnchors(rows, w, h, rand, w * h >= 144 ? 1 : 1);
}

// Blobby picture with rectangular outline holes carved into it —
// Mondrian-ish abstract. The carves create distinctive corner/single clues
// that make the puzzle mostly unique right away.
function makeShapes(w, h, rand) {
  const rows = randomBlobs(w, h, rand, 0.52);
  const carves = 2 + Math.floor(rand() * 3);
  for (let i = 0; i < carves; i++) {
    const rw = 2 + Math.floor(rand() * Math.min(6, w / 3));
    const rh = 2 + Math.floor(rand() * Math.min(6, h / 3));
    const x0 = Math.floor(rand() * Math.max(1, w - rw));
    const y0 = Math.floor(rand() * Math.max(1, h - rh));
    const x1 = x0 + rw - 1;
    const y1 = y0 + rh - 1;
    for (let x = x0; x <= x1; x++) {
      rows[y0] &= ~(1n << BigInt(x));
      rows[y1] &= ~(1n << BigInt(x));
    }
    for (let y = y0; y <= y1; y++) {
      rows[y] &= ~(1n << BigInt(x0));
      rows[y] &= ~(1n << BigInt(x1));
    }
  }
  return rows;
}

const PATTERNS = {
  symmetric: makeSymmetric,
  blobs: (w, h, r) => randomBlobs(w, h, r, 0.5),
  shapes: makeShapes,
  diagonal: makeDiagonal,
  checker: makeChecker,
};

// Large diagonal-stripe puzzles are genuinely Expert-class (their uniqueness
// is slow to prove and they need lots of human lookahead), so "auto" avoids
// them above 256 cells. They remain available by explicit --pattern.
const AUTO_PATTERNS = ['symmetric', 'blobs', 'shapes', 'checker'];
const AUTO_PATTERNS_SMALL = ['symmetric', 'blobs', 'shapes', 'diagonal', 'checker'];

const fillRatio = (rows, w, h) => rows.reduce((acc, row) => acc + popcount(row), 0) / (w * h);

// ---------------------------------------------------------------------------
// The generator itself.
// ---------------------------------------------------------------------------
function generatePuzzle(opts = {}) {
  const width = opts.width ?? 10;
  const height = opts.height ?? 10;
  const pattern = opts.pattern ?? 'auto';
  const allowed = opts.maxSolutions ?? 1; // "a few solutions"
  const minFill = opts.minFill ?? 0.35;
  const maxFill = opts.maxFill ?? 0.65;
  const minDiff = opts.minDifficulty ?? 'Easy'; // skip Trivial by default (non-trivial only)
  const maxDiff = opts.maxDifficulty ?? null;
  const verifyMs = opts.verifyMs ?? Math.max(400, width * height * 2);
  const overallMs = opts.overallMs ?? 8000;
  const maxImages = opts.maxImages ?? 20;
  const maxFlips = opts.maxFlips ?? 6;
  const seed = opts.seed ?? (Date.now() ^ Math.floor(Math.random() * 0xffffffff));
  const rand = mulberry32(seed);
  const t0 = Date.now();

  for (let img = 0; img < maxImages; img++) {
    if (Date.now() - t0 > overallMs) break;
    const autoList = width * height >= 256 ? AUTO_PATTERNS : AUTO_PATTERNS_SMALL;
    const name = pattern === 'auto' ? autoList[Math.floor(rand() * autoList.length)] : pattern;
    const makeFn = PATTERNS[name];
    if (!makeFn) throw new Error(`unknown pattern "${pattern}" (try symmetric, blobs, diagonal, checker, auto)`);

    let rows = makeFn(width, height, rand);
    if (fillRatio(rows, width, height) < minFill || fillRatio(rows, width, height) > maxFill) continue;

    for (let flip = 0; flip < maxFlips; flip++) {
      if (Date.now() - t0 > overallMs) break;
      const { rowClues, colClues } = cluesFromGrid(rows, width, height);
      const res = solvePuzzle(
        { width, height, rowClues, colClues },
        { maxSolutions: allowed + 1, timeBudgetMs: verifyMs }
      );
      if (res.timedOut) break; // uniqueness unprovable within budget → redraw
      if (res.solutions.length <= allowed) {
        const diff = classifyDifficulty(res.lineSolvablePercent, res.nodes, width * height);
        const di = DIFFICULTIES.indexOf(diff);
        const inRange =
          (minDiff === null || di >= DIFFICULTIES.indexOf(minDiff)) &&
          (maxDiff === null || di <= DIFFICULTIES.indexOf(maxDiff));
        if (inRange && res.solutions.some((s) => s.every((row, r) => row === rows[r]))) {
          return {
            width,
            height,
            rowClues,
            colClues,
            solution: rowsToArrays(rows, width),
            solutions: res.solutions.map((s) => rowsToArrays(s, width)),
            count: res.solutions.length,
            seed,
            pattern: name,
            difficulty: diff,
            lineSolvablePercent: res.lineSolvablePercent,
            searchNodes: res.nodes,
            verifyMs: res.elapsedMs,
            generatedMs: Date.now() - t0,
            generatedAt: new Date().toISOString(),
          };
        }
        break; // unique but wrong difficulty → redraw
      }
      // Rivals exist: flip a few cells where the picture disagrees with a
      // rival — killing several rival solutions at once converges faster
      // than flipping a single cell.
      const rival = res.solutions.find((s) => s.some((row, r) => row !== rows[r]));
      if (!rival) break;
      const diffs = [];
      for (let r = 0; r < height; r++) {
        let x = rows[r] ^ rival[r];
        while (x) {
          const low = x & -x;
          diffs.push([r, low.toString(2).length - 1]);
          x ^= low;
        }
      }
      // shuffle and take up to 3 differing cells
      for (let i = diffs.length - 1; i > 0; i--) {
        const j = Math.floor(rand() * (i + 1));
        [diffs[i], diffs[j]] = [diffs[j], diffs[i]];
      }
      let ratio = NaN;
      for (let k = 0; k < Math.min(3, diffs.length); k++) {
        const [r, c] = diffs[k];
        rows[r] ^= 1n << BigInt(c);
        ratio = fillRatio(rows, width, height);
        if (ratio < minFill || ratio > maxFill) break; // drifted out of bounds → redraw
      }
    }
  }
  return null; // gave up within the attempt budget
}

// ---------------------------------------------------------------------------

  globalThis.generatePuzzle = generatePuzzle;
  globalThis.classifyDifficulty = classifyDifficulty;
  globalThis.DIFFICULTIES = DIFFICULTIES;
})();
